<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('expenses.view');if($_SERVER['REQUEST_METHOD']==='POST')require_permission('expenses.edit');$bid=(int)$u['business_id'];$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=trim((string)($_POST['expense_date']??''));$cat=post_text('category',100);$desc=post_text('description');$amount=round((float)($_POST['amount']??0),2);if(!$date||!$cat||!$desc||$amount<=0)$error='Enter a date, category, description and positive amount.';else{$pdo->prepare('INSERT INTO expenses(business_id,expense_date,category,description,amount,method,vendor) VALUES(?,?,?,?,?,?,?)')->execute([$bid,$date,$cat,$desc,$amount,post_text('method',60)?:'Bank transfer',post_text('vendor')]);audit('expense.create',$desc.' '.money($amount));flash('Expense recorded.');redirect('expenses.php');}}$q=$pdo->prepare('SELECT * FROM expenses WHERE business_id=? ORDER BY expense_date DESC');$q->execute([$bid]);$rows=$q->fetchAll();$total=array_sum(array_column($rows,'amount'));page_start('Expenses','expenses');module_css('expenses');?><div class="section-head"><div><span class="eyebrow">CASH OUT</span><h1>Expenses</h1><p>Keep operating costs visible and connected to your cash flow.</p></div><button class="button primary" onclick="document.getElementById('record-modal').showModal()"><i class="ti ti-plus"></i> Add expense</button></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif?><div class="summary-grid"><div class="summary-tile"><small>Recorded expenses</small><strong><?=money($total)?></strong></div><div class="summary-tile"><small>Expense records</small><strong><?=count($rows)?></strong></div></div><div class="content-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>DATE</th><th>DESCRIPTION</th><th>CATEGORY</th><th>VENDOR</th><th>METHOD</th><th>AMOUNT</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=fmt_date($r['expense_date'])?></td><td class="table-strong"><?=e($r['description'])?></td><td><span class="pill"><?=e($r['category'])?></span></td><td><?=e($r['vendor']?:'—')?></td><td><?=e($r['method'])?></td><td class="table-strong"><?=money($r['amount'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty-row">No expenses recorded yet.</td></tr><?php endif?></tbody></table></div></div><?php $fields='<label>Date<input required type="date" name="expense_date" value="'.date('Y-m-d').'"></label><label>Category<input required name="category" placeholder="Travel, software…"></label><label class="wide">Description<input required name="description"></label><label>Amount<input required type="number" min="0.01" step="0.01" name="amount"></label><label>Method<select name="method"><option>Bank transfer</option><option>UPI</option><option>Cash</option><option>Card</option><option>Other</option></select></label><label>Vendor<input name="vendor"></label>';modal_form('Record expense','create',$fields);page_end();
